extern "C" char *strcpy(char *, const char *);
extern "C" char *strcat(char *, const char *);
extern "C" int WaitSema(int);
extern "C" int SignalSema(int);
extern "C" void ExitDeleteThread();

struct saveInfo
{
  float version;
  int type;
  char shortname[8];
  char desc[68];
  long int timestamp;
  int valid;
};

struct GameSaverThreadArgs
{
  int port;
  int slot;
  saveInfo *info;
  int maxItems;
  void *buffer;
  int size;
  void *iconData;
  int iconSize;
  bool overWrite;
  void(*progressCallback)(void *, int);
  void *userCallbackData;
};

class GenericGameSaver
{
public:
  unsigned char dastack[0x2011] __attribute__((aligned(16)));
  static GenericGameSaver *instance;
  static GenericGameSaver *inst() { return instance; }
  static void readFileHelper(void *data);
  static int readData(int port, int slot, char *name, void *data, int maxSize);
};

extern int MemoryCardSema;
extern bool bad_mc_stack_error;

__asm__(".equ strcpy, 0x003D3FCC");
__asm__(".equ strcat, 0x003D3BCC");
__asm__(".equ WaitSema, 0x003DB6A0");
__asm__(".equ SignalSema, 0x003DB680");
__asm__(".equ ExitDeleteThread, 0x003DB560");
__asm__(".equ readData__16GenericGameSaveriiPcPvi, 0x001E4C00");
__asm__(".equ MemoryCardSema, 0x0041E59C");
__asm__(".equ bad_mc_stack_error, 0x0041E514");
__asm__(".equ instance__16GenericGameSaver, 0x0041E5B8");

#define PRODUCT_CODE "BASLUS-20334"
#define GSOk 0
#define GSErrorBadVersion -9
#define CAREER_DATA_VERSION 68136
#define MC_STACK_SIZE 0x2000
#define STACK_WATCH 0xBE
#define CHECK_MC_STACK (!(GenericGameSaver::inst()->dastack[15] == STACK_WATCH && GenericGameSaver::inst()->dastack[MC_STACK_SIZE+1] == STACK_WATCH)?bad_mc_stack_error=true:0)

void GenericGameSaver::readFileHelper(void *data)
{
  char fname[100];
  saveInfo sInfo;
  GameSaverThreadArgs *args = (GameSaverThreadArgs *)data;
  WaitSema(MemoryCardSema);

  strcpy(fname, "/");
  strcat(fname, PRODUCT_CODE);
  strcat(fname, args->info->shortname);
  strcat(fname, "/");
  strcat(fname, "index.nfo");

  int error = readData(args->port, args->slot, fname, &sInfo, sizeof(saveInfo));
  if (error != GSOk)
  {
    SignalSema(MemoryCardSema);
		if (args->progressCallback)
      args->progressCallback(args->userCallbackData, error);
    CHECK_MC_STACK;
    ExitDeleteThread();
    return;
  }

  if (sInfo.version != CAREER_DATA_VERSION)
  {
    SignalSema(MemoryCardSema);
		if (args->progressCallback)
      args->progressCallback(args->userCallbackData, GSErrorBadVersion);
    CHECK_MC_STACK;
    ExitDeleteThread();
    return;


  }


  strcpy(fname, "/");
  strcat(fname, PRODUCT_CODE);
  strcat(fname, args->info->shortname);
  strcat(fname, "/");
  strcat(fname, PRODUCT_CODE);
  strcat(fname, args->info->shortname);

  error = readData(args->port, args->slot, fname, args->buffer, args->size);
  if (error != GSOk)
  {
    SignalSema(MemoryCardSema);
		if (args->progressCallback)
      args->progressCallback(args->userCallbackData, error);
		CHECK_MC_STACK;
    ExitDeleteThread();
    return;
  }

	SignalSema(MemoryCardSema);
  if (args->progressCallback)
    args->progressCallback(args->userCallbackData, 100);
  CHECK_MC_STACK;
  ExitDeleteThread();
  return;
}
